    {
      "citations": [
        {
          "event_id": "lite_evt_00047",
          "explanation": "Doctor asks about red-flag symptoms and gives clear emergency thresholds, meeting this RC.",
          "quote": "阴道出血、流水（哪怕一点点）、规律阵发性肚子疼一阵阵紧"
        },
        {
          "event_id": "lite_evt_00088",
          "explanation": "Turn 3 reinforces the red-flag screening with specific emergency signs.",
          "quote": "阴道出血或流水（哪怕一点点粉色或透明水）"
        }
      ],
      "explanation": "The doctor actively screens for bleeding, rupture of membranes, contractions, and fetal movement changes across multiple turns, and clearly states that any positive finding should lead to immediate hospital visit. This meets the RC fully.",
      "issue_kind": "none",
